static inline bool BM25UnicodeIsAlnum(uint32_t cp)
{
    if (cp < 128)
        return (cp >= 'A' && cp <= 'Z') || (cp >= 'a' && cp <= 'z') || (cp >= '0' && cp <= '9');
    unsigned int lo = 0;
    unsigned int hi = sizeof(bm25UnicodeAlnumRanges) / sizeof(bm25UnicodeAlnumRanges[0]);
    while (lo < hi) {
        unsigned int mid = lo + (hi - lo) / 2;
        if (cp < bm25UnicodeAlnumRanges[mid][0])
            hi = mid;
        else if (cp > bm25UnicodeAlnumRanges[mid][1])
            lo = mid + 1;
        else
            return true;
    }
    return false;
}

static inline int BM25UnicodeLower(uint32_t cp, uint32_t out[2])
{
    out[0] = cp;
    if (cp < 128) {
        if (cp >= 'A' && cp <= 'Z')
            out[0] += 'a' - 'A';
        return 1;
    }
    if (cp == 0x130) {  /* LATIN CAPITAL LETTER I WITH DOT ABOVE */
        out[0] = 0x69;
        out[1] = 0x307;
        return 2;
    }
    unsigned int lo = 0;
    unsigned int hi = sizeof(bm25UnicodeLowerPairs) / sizeof(bm25UnicodeLowerPairs[0]);
    while (lo < hi) {
        unsigned int mid = lo + (hi - lo) / 2;
        if (cp < bm25UnicodeLowerPairs[mid][0])
            hi = mid;
        else if (cp > bm25UnicodeLowerPairs[mid][0])
            lo = mid + 1;
        else {
            out[0] = bm25UnicodeLowerPairs[mid][1];
            break;
        }
    }
    return 1;
}
